import { EXAM_SOURCES } from './exam-spec.js';
import { readings, escapeHtml as esc } from './activities.js';
import { batteryPack, lampCircuit, antennaElementLength, signalsOverlap } from './physics.js';

const syllabus = (page, items) => ({ title: `RSGB Foundation syllabus ${items}`, url: `${EXAM_SOURCES.syllabus}#page=${page}` });
const physics = { title: 'OpenStax: current, voltage and Ohm’s law', url: 'https://openstax.org/books/university-physics-volume-2/pages/9-4-ohms-law' };
const waves = { title: 'OpenStax: how electromagnetic waves carry information', url: 'https://openstax.org/books/university-physics-volume-2/pages/16-5-the-electromagnetic-spectrum' };
const guidance = { title: 'Ofcom: amateur radio licence guidance', url: 'https://www.ofcom.org.uk/siteassets/resources/documents/manage-your-licence/amateur/amateur_radio_licence_guidance_for_licensees.pdf?v=405585' };

const guides = {
  radio: {
    intro: 'A radio link moves information between places without a signal cable joining them. It needs a way to represent the message, a transmitter to create the radio signal, and a receiver to recover the information. A signal-strength indication alone does not prove that the message can be understood.',
    terms: [['Transmitter', 'Equipment that generates a radio-frequency signal carrying information and supplies it to an antenna.'], ['Receiver', 'Equipment that selects an incoming radio signal and recovers the information carried by it.'], ['Radio wave', 'A travelling electromagnetic disturbance. It is different from a sound wave in air.']],
    steps: ['A message becomes a changing electrical signal. For example, a microphone produces a small voltage that follows sound-pressure changes; a data interface can supply a representation of text.', 'The transmitter puts that information onto a radio-frequency signal. Its antenna couples energy into the surrounding electromagnetic field. No voice or data needs to be played by this learning app to illustrate the process.', 'At the other end, a receiving antenna couples part of the incoming field into the receiver. The receiver must select the wanted signal and use the appropriate method to recover its information.', 'As a wave spreads, the available signal generally becomes weaker. Noise, interference and obstructions also matter, so a real usable link depends on more than transmitter power.'],
    example: 'Two people use handheld radios on a walk. They need suitable frequencies, compatible modes and a usable path in both directions. Hearing the other person does not prove that the other radio can hear you: the antennas, interference or transmitter powers may differ.',
    mistake: 'Sound does not travel from one radio to the other as a sound wave through the antenna. Information about the sound is carried by an electromagnetic wave and recovered at the receiving end.',
    sources: [syllabus(33, '3A1; 3H1; 5A1'), waves],
  },
  wave: {
    intro: 'Frequency and wavelength describe the same repeating wave in two different ways. Frequency counts repetitions at one place over time. Wavelength measures the distance occupied by one complete repetition at one instant. Connecting those descriptions explains why radio antennas can have very different physical sizes.',
    terms: [['Frequency, f', 'Complete cycles per second, measured in hertz (Hz). One megahertz (MHz) is one million cycles per second.'], ['Wavelength, λ', 'The distance from one point in a cycle to the equivalent point in the next cycle, such as adjacent peaks. It is measured in metres.'], ['Amplitude', 'The size of a wave’s variation about its centre value. Height on the drawing represents amplitude, not wavelength.']],
    steps: ['Radio waves in air travel at approximately 300 million metres per second. During one cycle they travel one wavelength. Therefore speed = frequency × wavelength.', 'With frequency expressed in MHz and wavelength in metres, the useful approximation is λ = 300/f. Divide 300 by the MHz value; do not put a hertz value into this MHz shortcut without converting units.', 'If frequency doubles while propagation speed stays effectively the same, there must be twice as many cycles within the same distance. Each cycle occupies half as much distance, so wavelength halves.', 'Many antenna designs use dimensions related to wavelength. An ideal quarter-wave element has length λ/4. Loading, the ground plane, materials and the installation alter real dimensions, so this is a physical explanation and starting estimate, not a complete construction plan.'],
    example: 'At 100 MHz, λ = 300/100 = 3 m, and λ/4 = 0.75 m. At 2,400 MHz, λ = 300/2400 = 0.125 m, and λ/4 = 0.03125 m, about 3.1 cm. This helps explain a long FM aerial beside a compact Wi-Fi antenna element. The labelled reference object uses the same physical scale as the element comparison.',
    mistake: 'Closer peaks do not mean the wave travels faster. They mean a shorter wavelength. A higher carrier frequency alone also does not specify data rate: bandwidth, modulation and signal quality matter.',
    sources: [syllabus(24, '2E7; 4D1'), waves, { title: 'Texas Instruments: antenna dimensions and wavelength, AN058', url: 'https://www.ti.com/lit/an/swra161b/swra161b.pdf' }],
  },
  units: {
    intro: 'A number on equipment is incomplete until you know what it measures and which unit is used. A prefix changes the size of the written unit, not the underlying physical quantity. Converting labels to a common unit prevents apparently different ratings from being confused.',
    terms: [['Volt, V', 'The unit of potential difference: electrical energy transferred per unit charge between two points.'], ['Ampere, A', 'The unit of current: the rate at which electric charge passes a point in a circuit.'], ['Prefix', 'A multiplier attached to a unit. Milli means one thousandth, kilo means one thousand, and mega means one million.']],
    steps: ['First identify the physical quantity: current, voltage, resistance, power or frequency. Amperes and volts cannot be compared as if they measured the same thing.', 'Write the prefix as a multiplier. For example, 1 mA is 0.001 A, while 1 kHz is 1,000 Hz. Keep the unit attached to the calculation.', 'Convert both values to the same unit. A larger number in smaller units need not represent a larger physical quantity.', 'Check whether the result makes sense: moving from amperes to the smaller milliampere unit makes the written number larger. It does not make the actual current larger.'],
    example: 'A label states 0.5 A. Multiply by 1,000 to express it as 500 mA. A second label stating 500 mA describes the same current. Likewise, 145 MHz is 145,000 kHz: both identify the same frequency.',
    mistake: 'A 2 A supply capability does not mean that every connected device is forced to draw 2 A. Voltage compatibility, the load and the supply’s current capability are separate matters.',
    sources: [syllabus(7, 'mathematics and symbols; 2A1'), physics],
  },
  symbols: {
    intro: 'A circuit diagram shows electrical relationships rather than a photograph of the equipment. Its symbols let you recognise the source, components and conducting paths even when the physical parts look different. Start by finding the source and tracing the connections.',
    terms: [['Cell symbol', 'One long and one short parallel line. The long line marks the positive terminal. Several cell pairs represent a battery.'], ['Resistor symbol', 'A component symbol, commonly a rectangle in this course, representing resistance in the current path.'], ['Open switch', 'A deliberate gap in the conducting path. It is not the same symbol as a closed connection.']],
    steps: ['Identify a component by its symbol before interpreting the diagram. A pair of equal parallel plates is a capacitor; unequal long/short plates indicate a cell.', 'Follow a wire from one source terminal through the connected components and back to the other terminal. A complete DC path allows current; an open point breaks that path.', 'Read labels and values next. They describe the electrical quantity or component value rather than the physical size of the drawn object.', 'Relate the symbol back to the object in the visual. A small rectangular cell and a much larger battery pack can serve the same diagrammatic role, while having different voltage, capacity and safety characteristics.'],
    example: 'In a torch diagram, locate the cell symbol, then the switch, then the lamp and the return wire. Opening the switch explains why the lamp goes out even though the cell remains fitted. You can understand the connection without seeing the torch’s casing.',
    mistake: 'The position or size of a symbol on the page is normally chosen for clarity. It does not by itself specify the component’s dimensions, power rating or physical installation position.',
    sources: [syllabus(7, 'prior requirements: symbols and diagrams; 2A2')],
  },
  circuit: {
    intro: 'A resistor gives a simple way to connect voltage, current and heating. Voltage is the electrical driving difference across it; current is the rate of charge flow through it; resistance describes how strongly it opposes that flow. A useful prediction needs all three ideas, rather than treating the numbers as unrelated labels.',
    terms: [['Potential difference, V', 'The difference in electrical energy per unit charge across two points, measured in volts.'], ['Current, I', 'Charge passing a point each second, measured in amperes. Current flows through the resistor.'], ['Resistance, R', 'Opposition to current, measured in ohms (Ω). An ideal fixed resistor obeys V = I × R.']],
    steps: ['The source establishes a voltage across a complete circuit. Charge already present in the conducting path moves in response to the resulting electric field.', 'For the ideal resistor, I = V/R. At the same voltage, doubling R halves the current. At the same R, doubling V doubles current.', 'To find a different unknown, rearrange the same relationship: V = I × R or R = V/I. Identify the requested quantity before substituting numbers.', 'The resistor also converts electrical energy to heat. Its power is P = V × I. A component’s real rating and temperature matter; the calculation alone does not certify that a resistor can safely dissipate that power.'],
    example: 'Keep V at 12 V. With R = 6 Ω, I = 12/6 = 2 A, and P = 12 × 2 = 24 W. Replace R by 12 Ω: I = 12/12 = 1 A and P = 12 W. The smaller current follows from greater opposition at the same driving voltage.',
    mistake: 'A resistor does not use up current so that less comes out of it in a single series path. The current is the same on each side; electrical energy is transferred to heat.',
    sources: [syllabus(18, '2B1; 2C1'), physics, { title: 'OpenStax: electrical current and charge flow', url: 'https://openstax.org/books/university-physics-volume-2/pages/9-1-electrical-current' }],
  },
  battery: {
    intro: 'A battery supplies electrical energy from chemical energy stored in its cells. It establishes a potential difference between its terminals. Connecting a suitable load gives that energy a path to be transferred; leaving the load disconnected can stop current without removing the battery’s voltage.',
    terms: [['Cell', 'One electrochemical source, such as an ideal 1.5 V cell in this model.'], ['Battery', 'A combination of cells. Series connections usually raise total voltage by adding the individual cell voltages.'], ['Load', 'The connected component or device that receives electrical energy. Here it is an ideal 6 Ω resistive load, not a full model of a radio.']],
    steps: ['Each cell has positive and negative terminals. In a series arrangement the positive terminal of one connects to the negative terminal of the next, so their driving voltages add.', 'Two ideal 1.5 V cells produce 3 V; three produce 4.5 V. This calculation concerns voltage. It does not alone tell you battery capacity, runtime or whether the supply is suitable for a real device.', 'With the model’s 6 Ω load connected, current is I = V/6. Increasing cell count raises voltage, so this same resistive load draws more current and receives more power.', 'Opening the load path makes current and delivered power zero in the model. Stored chemical energy and the terminal voltage can remain. An unused cell therefore still needs suitable handling and terminal protection.'],
    example: 'Two cells give V = 2 × 1.5 = 3 V. The connected 6 Ω load draws I = 3/6 = 0.5 A and receives P = 3 × 0.5 = 1.5 W. Disconnect it: I becomes 0 A and P becomes 0 W, while the ideal battery remains at 3 V.',
    mistake: 'More cells are not automatically a useful upgrade. A real device has a specified voltage range and battery chemistry. Exceeding them can damage the device or create a hazard.',
    sources: [syllabus(31, '2J1; 8A8'), physics],
  },
  connection: {
    intro: 'A working circuit needs an appropriate continuous electrical path. A switch controls that path deliberately; a loose connector or broken conductor may interrupt it unintentionally. Distinguish the presence of a source from the presence of a complete connection.',
    terms: [['Closed path', 'A continuous conducting route appropriate to the circuit. In a simple DC circuit it joins both source terminals through the load.'], ['Open circuit', 'A break that prevents current through that route in this ideal model.'], ['Insulation', 'Material that resists unintended current paths. Moisture or damage can compromise its protection.']],
    steps: ['Trace the intended path rather than just counting the visible components. A battery and a lamp can both be present while an open switch prevents current.', 'Closing the switch joins the gap. In the ideal torch example, 3 V across 6 Ω gives 0.5 A, so energy is transferred to the lamp.', 'Opening the switch breaks the common path and the lamp current stops. The source can still have a voltage; zero load current does not prove the whole equipment is harmless.', 'An RF connector additionally has to suit the feeder: its contact and screen termination affect continuity, shielding and impedance. The RF connector scene is qualitative and does not use the torch’s 6 Ω calculation.'],
    example: 'A torch fails after being dropped. Before assuming its lamp or battery is faulty, a missing electrical connection is a possible cause. In a radio station, a loose accessible RF connector is similarly a different fault from selecting the wrong frequency.',
    mistake: 'A connector that fits mechanically is not necessarily electrically correct. Connector type, termination, screening and the equipment’s requirements still matter.',
    sources: [syllabus(17, '2A1; 2A2; 4G1'), physics],
  },
  power: {
    intro: 'Power describes the rate of energy transfer. It tells you how many joules are transferred each second, rather than how much energy has been stored in total. For a DC device at a specified operating point, voltage and current together determine this rate.',
    terms: [['Power, P', 'Energy transferred per second, measured in watts. One watt is one joule per second.'], ['Voltage, V', 'Electrical energy available per unit charge across the supply or load.'], ['Current, I', 'Charge flow per second. Combining energy per charge with charge per second gives energy per second.']],
    steps: ['Identify the voltage actually applied and the current actually drawn. A label showing a maximum current capability is not necessarily the operating current of every load.', 'Use P = V × I. Keep volts, amperes and watts attached to the arithmetic so that an incorrect substitution is easier to spot.', 'For another unknown, use I = P/V or V = P/I. The physical relationship is the same even though the calculation is rearranged.', 'In real USB charging, the supply, cable and device must support the operating arrangement. A larger watt rating alone does not guarantee that a particular device charges at that rate.'],
    example: 'At 5 V and 2 A, P = 5 × 2 = 10 W: ten joules per second. At 5 V and 3 A, P = 15 W. If an 18 W load operates at 9 V, its current is I = 18/9 = 2 A.',
    mistake: 'Watts and stored battery capacity are different concepts. A high-power load may use stored energy faster, but runtime also depends on the battery’s usable energy and the actual operating pattern.',
    sources: [syllabus(18, '2B1'), physics],
  },
  series: {
    intro: 'Series and parallel describe connections, not the appearance of components on the page. A series circuit has one shared route through its loads. Parallel loads have separate branches across the same supply terminals. These arrangements respond differently to an open-circuit fault.',
    terms: [['Series', 'Components connected along one unbranched path, with the same current through them.'], ['Parallel', 'Branches connected across the same two points, with the same potential difference across each branch.'], ['Open-circuit fault', 'A broken path. It is different from a short circuit, which provides an unintended low-resistance path.']],
    steps: ['The example has a 6 V source and two ideal 6 Ω resistive lamps. In series their total resistance is 12 Ω, so the current is 6/12 = 0.5 A through each lamp.', 'Each equal series lamp has 3 V across it. Their voltage drops add to the 6 V supply. Current is shared by following the same path; it is not divided between the two series lamps.', 'In parallel each lamp is directly across 6 V, so each branch current is 6/6 = 1 A. The source supplies the sum: 2 A.', 'Open the first lamp. In series the only path is broken and both stop. In parallel the second branch is still complete and remains supplied at 6 V, so its current continues.'],
    example: 'This explains why one failed load can stop a simple series string while another independently connected branch keeps operating. Real decorative lights may include bypasses or electronic drivers, so do not assume every commercial light string matches the ideal drawing.',
    mistake: 'Parallel does not mean that the supply voltage is divided equally between the branches. The branch voltage is the same; their currents depend on their loads.',
    sources: [syllabus(17, '2A2; 2C1; 2C2'), { title: 'OpenStax: series and parallel circuits', url: 'https://openstax.org/books/university-physics-volume-2/pages/10-2-resistors-in-series-and-parallel' }],
  },
  powerType: {
    intro: 'DC and AC describe how a voltage or current behaves over time. A steady battery has a fixed polarity. An alternating supply reverses polarity repeatedly, so the direction of current through a suitable resistive load also reverses. The trace makes that reversal visible.',
    terms: [['DC — direct current', 'Current with one direction. A steady battery is a familiar source of approximately constant-polarity voltage.'], ['AC — alternating current', 'Current whose direction reverses periodically. The plotted positive and negative parts indicate opposite directions or polarities.'], ['Cycle', 'One complete repeat of the waveform, including both halves of an alternating cycle.']],
    steps: ['Read the horizontal axis as time, not distance. Read the centre line as zero. A DC trace remaining on one side indicates one polarity.', 'For the sine-wave AC example, the trace rises, falls through zero, changes sign and returns to its starting state. That full sequence is one cycle.', 'The UK mains frequency is 50 Hz, so there are 50 complete cycles per second. This does not mean a supply is 50 V: frequency and voltage are separate quantities.', 'A suitable charger or power supply converts and regulates the input to what the device needs. A battery-powered device expecting DC should receive the specified type, polarity and voltage.'],
    example: 'The wall supply and a handheld’s battery do different electrical jobs. The charger’s input may be mains AC while its controlled charging output is suitable for a DC battery system. The workbench compares waveform types; it is not a mains-wiring exercise.',
    mistake: 'AC does not mean large current, and DC does not mean safe. Both the operating voltage and the possible fault current must be considered.',
    sources: [syllabus(21, '2E1; 2E2; 8A1')],
  },
  digital: {
    intro: 'A computer cannot process a continuously varying voltage as an unlimited collection of values. A sampling stage measures it at particular instants and represents those measurements digitally. Software can then select, analyse or encode the information represented by those samples.',
    terms: [['Analogue signal', 'A signal whose relevant quantity varies continuously rather than only at selected measurement instants.'], ['Sample', 'A measured value taken at one instant. A sequence of samples represents how the input varies over time.'], ['ADC and DAC', 'An analogue-to-digital converter produces a digital representation of an analogue input. A digital-to-analogue converter produces an analogue output from digital values.']],
    steps: ['The dashed curve represents the original continuously changing input. The marked points are the values captured at the selected instants.', 'Increasing sample count across this same time window takes measurements more closely together. The displayed approximation can follow the curve more closely. Real sampling also has limits involving rate, signal bandwidth and numerical resolution.', 'An SDR digitises a received input and uses software for functions such as filtering and demodulation. The computer still needs suitable input conversion and RF hardware.', 'Digital voice and data need agreed encoding and compatible system settings. Sampling is one part of their processing, not a complete explanation of every codec or communication protocol.'],
    example: 'A computer-connected receiver can show and process several signals present in its sampled input. Selecting a software filter changes which part is processed. Two DV radios on the same frequency may still be incompatible if their radio systems or settings do not agree.',
    mistake: 'Digital does not mean infinitely accurate or automatically intelligible. More plotted samples illustrate one improvement, but noise, sampling arrangements, encoding and compatibility still matter.',
    sources: [syllabus(24, '2F1; 2F2; 3M1; 7F1')],
  },
  signal: {
    intro: 'A transmitter must create a radio-frequency signal, make controlled changes to it that represent a message, and supply enough RF power to the antenna. These are separate jobs. The boxes show those jobs in a simplified functional chain, rather than four different names for the same operation.',
    terms: [['Carrier', 'A regular radio-frequency electrical oscillation. On its own it has no changing voice or data message. It is the signal that can be varied to carry that information.'], ['Oscillator', 'A circuit that generates a repeating electrical signal at a chosen frequency. In this simple transmitter it provides the carrier.'], ['Modulator', 'The function that varies the carrier according to the information input. AM varies amplitude; FM varies instantaneous frequency.'], ['RF amplifier', 'A stage that draws energy from the power supply to increase RF signal power. It should preserve the intended modulation.']],
    steps: ['Start with the information. A microphone turns changing sound pressure into a small electrical signal, or a data interface supplies an electrical representation of information. This is the message input, not yet the RF signal sent by the antenna.', 'The oscillator separately creates the carrier. For an example FM transmitter set to 145 MHz, the carrier repeats about 145 million cycles per second. This gives the radio signal its operating frequency; it does not by itself contain your changing message.', 'The modulator uses the message to control the RF signal. With AM, the RF wave height follows the message. With FM, instantaneous RF frequency varies about the selected carrier frequency. This creates a recoverable relationship between the information and the RF waveform.', 'The RF power amplifier raises the modulated signal’s power using energy from the supply. It does not create the missing message if the message input is absent. The antenna then couples the electrical RF signal into electromagnetic waves.', 'A receiving radio selects the transmission and demodulates it: it measures the controlled changes and recovers the information they represent. It therefore needs the appropriate mode as well as the intended frequency.'],
    example: 'Compare two faults. If the oscillator is off, this model has no carrier to modulate or amplify, so the chain has no useful RF output. If the oscillator works but the message input is missing, a carrier can still pass through the ideal chain, yet it contains none of the intended changing information. Another station may detect a signal without recovering your message.',
    mistake: 'Physically removing a complete modulator stage from a series RF path is not necessarily the same as losing its message input. The latter is the fault simulated here. Real transmitter architectures vary; these blocks represent functions rather than a universal circuit layout.',
    sources: [syllabus(33, '3A1–3A4; 3B1; 3C1; 3E1; 3F1; 3H1'), waves],
  },
  modulation: {
    intro: 'A steady radio-frequency carrier tells a receiver that a signal is present, but a message needs a pattern of controlled changes. Modulation creates that pattern. Demodulation at the receiver measures the corresponding changes to recover the original information.',
    terms: [['Carrier', 'The radio-frequency oscillation about which the transmission is formed. It is much faster than an ordinary audio message.'], ['AM — amplitude modulation', 'The information controls the carrier’s amplitude, visible as changing RF wave height.'], ['FM — frequency modulation', 'The information controls instantaneous carrier frequency, visible as changing cycle spacing at essentially constant amplitude.']],
    steps: ['Read the slowly changing message trace first. It represents how the information varies, not the RF carrier itself. The drawings are normalised illustrations, not actual 145 MHz timing.', 'In AM the message changes the envelope, or overall height outline, of the rapid RF cycles. The receiver can recover information from those amplitude variations.', 'In FM the rapid cycles become closer together and farther apart about the nominal carrier frequency. Ideal amplitude stays constant. The receiver must recover the frequency variations rather than treating wave height as the message.', 'With message strength set to zero, this model has no message-driven variation and shows an unmodulated carrier. Real overmodulation or excessive deviation can distort a signal or occupy too much spectrum; more drive is not always better.'],
    example: 'Two receiving radios are tuned to the same transmission. One uses the correct demodulation mode and can recover the intended information. The other may fail despite having a strong signal indication, because it is measuring the wrong property.',
    mistake: 'The message’s frequency and FM frequency deviation are different quantities. FM is not simply a permanent upward move of the carrier: the instantaneous frequency varies above and below its nominal value.',
    sources: [syllabus(33, '3A1–3A4; 3G1'), waves],
  },
  tuner: {
    intro: 'A receiving antenna can pick up several transmissions at once. Tuning tells the receiver which part of the incoming spectrum to select. Recovering the selected programme then needs the appropriate demodulation and output processing. Tuning is therefore a selection operation, not a change in radio-wave speed.',
    terms: [['Tuning', 'Setting the receiver’s selected frequency or channel.'], ['Selection/filtering', 'Passing the wanted part of the input while reducing signals outside the selected range.'], ['Demodulation', 'Recovering the information represented by changes in the selected modulated signal.']],
    steps: ['Both fictional transmitters continue to exist: one at 100 MHz and the other at 104 MHz. Moving the dial does not move either transmitter’s signal.', 'The simplified selection rule accepts the programme close to its centre frequency. The readout identifies which transmission is selected, or says that neither example is selected.', 'The receiver’s later stages recover and amplify the information. In the app a text programme display represents that result, with no audio playback.', 'A real receiver also depends on signal level, filter bandwidth, interference, mode and many other settings. The narrow acceptance window in this model is a teaching rule, not a measured selectivity specification.'],
    example: 'A working portable radio can deliver the wrong programme because it is tuned to the wrong transmission. Before concluding it is broken, connect the tuning readout to the station you intended to select. Speaker volume alone does not choose the station.',
    mistake: 'Louder recovered audio does not prove correct tuning, and a strong RF indication does not prove the correct demodulation mode or intelligible output.',
    sources: [syllabus(39, '3H1; 3H2; 3K1; 3M1')],
  },
  keying: {
    intro: 'Information can be represented by when a signal is present and absent. Morse is a familiar example: agreed patterns of short and long marks represent characters. A receiving system must recognise the pattern and its timing to recover the intended text.',
    terms: [['CW', 'In this learning context, a radio-frequency carrier keyed on and off for Morse communication.'], ['Dot and dash', 'Short and long marks in the code. Their durations and the gaps between them distinguish the symbols.'], ['Encoding', 'An agreed way to represent information using signal changes. Different data systems use different representations.']],
    steps: ['Read the strip from left to right as time. The short and long rectangles show marks, while the spaces matter as well.', 'Key down means the carrier is present; key up means it is absent. The static RF trace makes this difference visible without sound or flashing.', 'Changing SOS to HI changes the agreed pattern representing the characters, rather than requiring the carrier to speak the letters.', 'Other data modes can use tones or other signal changes through an appropriate interface. They still require compatible encoding, timing, mode and levels. Morse illustrates the principle; it is not every digital protocol.'],
    example: 'SOS has three short marks, three long marks and three short marks, grouped into its three letters. A receiver that sees only an uninterrupted carrier cannot infer those letters; the pattern of changes carries them.',
    mistake: 'A publicly understood code such as ordinary Morse is not secret encryption merely because the listener needs to know the code.',
    sources: [syllabus(34, '3A2; 3A4; 1C2; 7D1')],
  },
  sidebands: {
    intro: 'A modulated transmission does not consist only of one carrier frequency. The information-bearing variations produce additional frequency components around it. A spectrum drawing shows where these components are, whereas an ordinary wave trace shows how voltage changes over time.',
    terms: [['Spectrum', 'A representation of a signal’s frequency components. Left and right mean lower and higher frequency, not earlier and later time.'], ['Sidebands', 'Frequency components generated around the carrier by modulation. The upper sideband is above the carrier frequency; the lower is below it.'], ['SSB', 'Single-sideband modulation: one sideband is transmitted while the carrier and the other sideband are suppressed.']],
    steps: ['Locate the carrier reference in the middle of the drawing. The left position is a lower frequency and the right position a higher frequency.', 'Conventional AM has a carrier and both sidebands. For a single simple tone, the schematic can show one line on either side; speech produces occupied bands rather than only two isolated lines.', 'Select USB or LSB. The corresponding information-bearing sideband remains, while the carrier and opposite sideband are suppressed in this illustration.', 'The receiver must use the appropriate demodulation method to recover the information. A frequency display and signal-strength indication alone do not identify the correct receiving mode.'],
    example: 'A radio offers AM, USB and LSB buttons. Those settings describe different ways information occupies the spectrum, not merely different loudness levels. Choosing USB for an intended LSB signal can prevent useful recovery.',
    mistake: 'The gap between drawn spectral lines is a frequency difference. It is not the physical distance between antennas or the amplitude of the transmitted wave.',
    sources: [syllabus(34, '3A3; 3A4')],
  },
  antenna: {
    intro: 'An antenna is the part that couples electrical RF signals to electromagnetic waves, and incoming waves back to electrical signals. Its shape, size and orientation affect which frequencies and directions it suits. A pattern drawing and a physical drawing answer different questions, so read them together.',
    terms: [['Element', 'A conducting part of the antenna involved in its radio-frequency behaviour.'], ['Radiation pattern', 'Relative response in different directions, shown for a specified plane. It is not a geographical coverage map.'], ['Dipole, ground plane and Yagi', 'Different antenna arrangements: a dipole has two arms, a ground-plane vertical has a radiating element and conducting return structure, and a Yagi uses several elements to form a directional pattern.']],
    steps: ['Find the physical antenna on the right and identify the radiating element or arms. The feeder joins at the feed point; the support is not automatically the radiating element.', 'Relate a full-size element to wavelength. A half-wave dipole is about λ/2 overall. A quarter-wave ground-plane element is about λ/4. A five-eighths-wave vertical uses 5λ/8 and needs an appropriate feed arrangement.', 'Read the pattern on the left as directions viewed from above. The radius indicates relative response, not distance travelled. A horizontal dipole favours its broadside directions; a Yagi favours its main-lobe direction.', 'Changing frequency changes the wavelength-related size estimate. Rotating a directional antenna rotates the favoured direction. These are different effects: one concerns dimensions, the other orientation.'],
    example: 'At 15 MHz, λ = 300/15 = 20 m. An ideal half-wave dipole is 10 m overall, a quarter-wave element is 5 m, and a five-eighths-wave element is 12.5 m. Real antennas require design and installation adjustments. A rooftop TV Yagi also illustrates why pointing direction can matter.',
    mistake: 'A larger drawing or larger physical antenna does not automatically mean more useful gain everywhere. Frequency suitability, pattern, height, losses, polarisation and installation all matter.',
    sources: [syllabus(47, '4C1–4D1'), { title: 'TI: physical antenna dimensions and wavelength', url: 'https://www.ti.com/lit/an/swra161b/swra161b.pdf' }],
  },
  feeder: {
    intro: 'The feeder carries an RF signal between the radio and antenna. It is a transmission line rather than an ideal invisible connection. Some energy becomes heat along it, so not all the transmitter’s output reaches the antenna. A received signal is also weakened on its way back to the receiver.',
    terms: [['Coaxial cable', 'An unbalanced feeder with a centre conductor surrounded by a conducting screen and insulation.'], ['Loss', 'A reduction in signal power due to energy dissipated or otherwise unavailable at the output. Feeder loss is often specified in decibels for a particular length and frequency.'], ['Screen', 'The coaxial outer conductor, which helps contain the wanted field and reduce unwanted coupling when correctly terminated.']],
    steps: ['The transmitter supplies RF power to the feeder input. The cable guides the signal towards the antenna through its conductor-and-field arrangement.', 'Real conductors and insulating materials have losses. Some of the input energy is dissipated along the cable instead of reaching the far end. The heat marks represent this dissipation, not a reflected signal coming back.', 'Longer runs of the same cable generally have more loss. Loss also generally increases with frequency, making suitable low-loss cable especially important at VHF/UHF.', 'On receive, the same feeder lies between the antenna and receiver. Improving a lossy feeder can therefore improve both directions, whereas increasing only transmit power does not improve receive performance.'],
    example: 'With 10 W entering a feeder and approximately 3 dB loss, about 5 W reaches the antenna. The remaining power is largely dissipated. A cable’s actual loss must be taken from its specification for the intended frequency and length; the slider is an example value.',
    mistake: 'Dissipated feeder power and reflected power are different. A lossy line can waste power even with a well-matched antenna, while a mismatch can cause reflection in a low-loss line.',
    sources: [syllabus(46, '4A1; 4A2; 4G1'), { title: 'Cisco radio training: decibels and power ratios', url: 'https://www.cisco.com/E-Learning/bulk/guest/celc/fwl/ch3/3_2_2/content.html' }],
  },
  matching: {
    intro: 'A transmitter and feeder are designed to work into a suitable load impedance. When the antenna system presents a different impedance, some forward RF power is reflected. The forward and reflected waves combine along the line to produce standing-wave maxima and minima.',
    terms: [['Impedance', 'The electrical relationship between RF voltage and current at a connection, including effects beyond simple DC resistance.'], ['SWR', 'Standing wave ratio: a measure related to the voltage maxima and minima created by forward and reflected waves on a line. A value of 1:1 corresponds to a matched ideal line.'], ['AMU or ATU', 'An antenna matching unit, often called a tuner, that transforms the impedance presented to the transmitter.']],
    steps: ['Forward power travels from the transmitter towards the antenna. A load matched to the feeder accepts that forward power without reflection in the ideal model.', 'A mismatch returns some power along the feeder. Increasing the model’s SWR increases the reflected fraction. The return path is deliberately drawn separately from the forward path.', 'A high transmitter-side SWR is a reason to investigate the antenna, feeder and connections. It is not by itself a diagnosis of a defective transmitter.', 'A suitable matching unit can transform the load seen by the transmitter. That can permit proper output-stage operation, but it does not remove every feeder or antenna loss or prove the antenna radiates efficiently.'],
    example: 'Optional model calculation: reflected fraction = ((SWR − 1)/(SWR + 1))². At 3:1 this is ((3 − 1)/(3 + 1))² = (2/4)² = 0.25, or 25%. From 10 W forward, reflected power = 10 × 0.25 = 2.5 W, leaving 10 − 2.5 = 7.5 W accepted at the load. This ideal-line calculation explains the display; the Foundation focus is recognising mismatch and what SWR indicates. A real installation also has losses and equipment-specific protection.',
    mistake: 'A low SWR is not a complete antenna-performance certificate. A dummy load can have an excellent match while deliberately radiating very little useful signal.',
    sources: [syllabus(51, '4C6; 4E1; 4E2; 4F1'), { title: 'Texas Instruments AN058, section 3.4: VSWR and reflection', url: 'https://www.ti.com/lit/an/swra161b/swra161b.pdf#page=6' }],
  },
  feedpoint: {
    intro: 'The feed point is the connection where the feeder joins the antenna. Its position matters because RF voltage and current vary along an antenna. Changing that position can change the impedance presented to the feeder, even though the same piece of wire is still visible.',
    terms: [['Feed point', 'The antenna connection at which the feeder supplies or receives the RF signal.'], ['Feed-point impedance', 'The RF voltage/current relationship presented by the antenna at that connection and frequency.'], ['Return arrangement', 'The rest of the conducting and field system needed for the feed to operate; an end-fed wire does not make the rest of the RF system irrelevant.']],
    steps: ['Locate the highlighted junction rather than looking only at the overall wire length. A centre-fed arrangement connects near the middle; an end-fed arrangement connects at an end.', 'At a particular frequency, different positions can have different RF voltage and current relationships. A feed arrangement suitable at one point may be unsuitable at another.', 'Compare the required matching and return arrangements, not just which connector reaches the wire conveniently. End-fed installations need a suitable design for both.', 'A mismatch with the feeder can reflect power. The diagram changes connection position only; it does not calculate a real wire’s impedance or give a complete installation plan.'],
    example: 'You can reach only one end of a garden wire with the feeder. That practical convenience explains choosing an end-fed design, but it does not mean ordinary coax can simply be joined without considering matching and the return path.',
    mistake: 'Changing the feed point is not the same as changing the transmitter’s carrier frequency. It changes how the antenna system is electrically connected at that frequency.',
    sources: [syllabus(49, '4C6; 4D1; 4E1')],
  },
  balun: {
    intro: 'A balanced antenna connection and an unbalanced coaxial feeder have different electrical arrangements. A suitable balun provides the transition between them. The name describes this role; it does not mean every balun has the same impedance ratio, current behaviour or frequency range.',
    terms: [['Balanced', 'An arrangement with corresponding conductors carrying equal and opposite signal behaviour relative to the system. A dipole is the standard example here.'], ['Unbalanced', 'An arrangement in which the signal conductor and its reference conductor have different roles. Coax has a centre conductor and an outer screen.'], ['Balun', 'A balanced-to-unbalanced transition device, selected for the intended antenna, feeder and frequency range.']],
    steps: ['Highlight the two dipole arms. They form the balanced antenna connection rather than a centre conductor surrounded by a screen.', 'Highlight the coax. Its inner and outer conductors form the unbalanced feeder arrangement.', 'Locate the balun where these arrangements meet. Depending on design it can address the required transition and unwanted current behaviour; its other electrical properties must be appropriate.', 'Keep balance and impedance matching separate in your reasoning. A particular balun may also transform impedance, but that is a design property, not a consequence of the word balun alone.'],
    example: 'A garden dipole is to be fed by coaxial cable. The useful question is how to make a suitable balanced-to-unbalanced transition at the antenna, rather than assuming the cable’s screen makes the entire antenna balanced.',
    mistake: 'Balanced does not mean good and unbalanced bad. Both arrangements are useful; the transition between them must suit the system.',
    sources: [syllabus(47, '4A1; 4B1')],
  },
  gain: {
    intro: 'A passive directional antenna can produce a stronger field in a favoured direction without creating energy. It distributes the supplied RF energy differently. ERP expresses the equivalent power relative to a reference dipole in that direction, so it combines supplied antenna power and directional gain.',
    terms: [['Gain', 'Relative response or radiation in a particular direction compared with a stated reference antenna.'], ['dBd', 'Gain expressed in decibels relative to a half-wave dipole. The reference matters when comparing figures.'], ['ERP', 'Effective radiated power: power applied to the antenna multiplied by its power gain factor relative to a dipole.']],
    steps: ['Keep the transmitter power fixed at 10 W. The antenna has no additional power source that could create more total energy.', 'Increase the directional gain. The illustrated beam concentrates the response in the favoured direction; the changing outline is qualitative rather than a measured antenna pattern.', 'For an ERP calculation, multiply the power at the antenna by the appropriate linear gain factor. A decibel value is not itself the factor: the workbench converts its dBd setting.', 'Check which power definition an operating limit uses. A limit expressed as ERP must include antenna gain, rather than considering only the transmitter’s output setting.'],
    example: 'If 6 W reaches an antenna whose gain factor relative to a dipole is 4, ERP = 6 × 4 = 24 W in the favoured direction. The passive antenna has not generated an extra 18 W of energy; the comparison concerns directionality.',
    mistake: 'A gain number without its reference can mislead. Also, more directional gain does not mean improved coverage equally in every direction.',
    sources: [syllabus(48, '4C3; 4C4; 1H1')],
  },
  polarisation: {
    intro: 'The electric field of a linearly polarised radio wave has an orientation. A straight antenna’s orientation is related to that polarisation. A receiving antenna aligned with the incoming polarisation normally couples to the wanted direct-path signal better than one at right angles.',
    terms: [['Polarisation', 'The orientation of the radio wave’s electric-field variation. It is separate from the direction in which the wave travels.'], ['Vertical and horizontal', 'Two linear orientations, illustrated by upright and horizontal straight antenna elements.'], ['Mismatch', 'A difference between the incoming polarisation and the receiving antenna orientation that can reduce coupling.']],
    steps: ['Start with both handheld antennas upright. The ideal direct-path model has aligned linear polarisations and shows maximum relative coupling.', 'Rotate one antenna. Its alignment with the incoming field changes, even though the radios’ frequencies and transmitter powers do not.', 'At a right angle the ideal direct-path model gives zero coupling. Real reflections and antenna patterns can leave other paths, so this is not a prediction that every real signal disappears completely.', 'For Foundation study, connect the antenna orientation to polarisation and the benefit of matching the ends. The displayed percentage is a model illustration; you do not need to infer real coverage from it.'],
    example: 'One walker holds a handheld upright while the other lays the aerial sideways. Restoring similar antenna orientations can improve a direct link without increasing transmitter power. Terrain and other factors may still limit the contact.',
    mistake: 'Polarisation is not the same as AM or FM. It concerns field orientation; modulation concerns how information changes a signal.',
    sources: [syllabus(47, '4C1; 4C5')],
  },
  propagation: {
    intro: 'Propagation describes how radio energy travels through the environment between stations. A transmitter can be working correctly while no usable path exists to the intended receiver. Frequency, terrain, antenna position and atmospheric conditions can change which routes are available.',
    terms: [['Line of sight', 'A direct geometrical path between points. Radio paths can be obstructed or affected even when there is some visual clearance.'], ['Ionosphere', 'Upper-atmosphere regions containing ionised gases. The Foundation syllabus describes relevant layers around 70–400 km altitude.'], ['Skywave', 'A path in which suitable radio waves are refracted through the ionosphere and return towards the Earth.']],
    steps: ['The direct path joins the two antenna positions. Add a hill and observe how that route becomes obstructed. Buildings and terrain can also weaken signals.', 'At suitable HF frequencies, changing ionospheric conditions can allow a wave to return towards the Earth beyond the direct horizon. This does not happen reliably on every frequency at every time.', 'The ionosphere is influenced by solar radiation. Time of day, season, solar activity and frequency affect the useful HF paths, so yesterday’s successful contact does not guarantee today’s.', 'VHF/UHF generally passes through the ionosphere, while terrain, antenna height and lower-atmosphere effects are important. Ducting and sporadic E can sometimes extend the range beyond the simple path drawn here.'],
    example: 'Two walkers have trouble on opposite sides of a hill. Moving to a suitable clearer position or using an available repeater may help. A garden HF station contacting a distant country may rely on quite a different, changing ionospheric route.',
    mistake: 'HF does not always travel farther, and a bigger transmitter does not guarantee a usable two-way path. A path must exist and each receiver must recover the signal.',
    sources: [syllabus(53, '5A1–5C3'), { title: 'NOAA Space Weather Prediction Center: HF radio paths', url: 'https://www.spaceweather.gov/impacts/hf-radio-communications' }],
  },
  rules: {
    intro: 'Qualification, operating authorisation and day-to-day compliance are separate steps. Passing an examination demonstrates the required qualification. The licence issued by Ofcom provides the operating authority and its conditions. Keeping those details correct remains part of being a licensee.',
    terms: [['RSGB', 'The Radio Society of Great Britain, which administers the amateur examinations described by the syllabus.'], ['Ofcom', 'The UK communications regulator and amateur-radio licence issuer.'], ['Call sign', 'The station identity assigned under the licence and used as required to identify the operation.']],
    steps: ['Study the relevant syllabus and demonstrate the required knowledge in the examination. The Foundation examination has a defined content allocation and pass benchmark.', 'A pass provides the qualification for the relevant application. It is not itself the document granting a new operator their own call sign and operating permission.', 'Apply to Ofcom and obtain the licence and assigned identity before operating under that licence. Read the conditions rather than assuming any frequency shown on the radio is permitted.', 'Keep name and address information up to date and validate the licence details at least every five years. Observe identification, interference, frequency, power and other applicable conditions when operating.'],
    example: 'A new candidate passes on Monday and wants to make a first contact under their own call sign. The next step is obtaining the Ofcom licence. Operating under someone else’s appropriate direct supervision is a separate provision with its own identification and responsibility.',
    mistake: 'A course-completion tick, a practice pass, an exam qualification and an operating licence do not mean the same thing. The app records each learning activity honestly.',
    sources: [syllabus(9, '1A1–1D2'), guidance],
  },
  callsign: {
    intro: 'A call sign identifies the station’s operation. Optional location or operating-situation information can be added in defined ways, but it must not obscure the assigned identity. Regional locators and suffixes play different roles and are therefore shown separately.',
    terms: [['Regional secondary locator', 'A letter used in the defined position to identify a UK region. Its correct use matters when included.'], ['Suffix', 'Additional identification after the call sign, often following a slash, such as /P for portable.'], ['Identification', 'Making clear which licensed station is transmitting, using an appropriate form for the mode and the required occasions.']],
    steps: ['Start with the fictional Foundation identity M7LAB. It is an example, not an assigned call sign available for this learner to use.', 'Changing region changes the appropriate optional locator shown in this example: W for Wales, M for Scotland or I for Northern Ireland. An omitted locator is shown as omitted rather than invented.', 'Changing operating situation adds the common optional suffix /P or /M in the illustration. A suffix does not change the licence’s frequencies or power limits.', 'The syllabus has a separate rule for 2x-series call signs, whose regional locator is mandatory. Do not generalise the M7 example to every call-sign format.'],
    example: 'The M7LAB example operating in Wales may be shown as MW7LAB. Portable operation may add /P, giving MW7LAB/P. The main identity is retained while the optional parts describe region and situation.',
    mistake: 'A regional locator or /P suffix does not authorise overseas operation. Appropriate destination permission must still be checked.',
    sources: [syllabus(10, '1A2; 1A4; 7A4'), guidance],
  },
  policy: {
    intro: 'A radio can be technically capable of a transmission while the proposed use remains outside the amateur licence’s purpose. Licence questions therefore ask about what the communication is for, not only which equipment or frequency is used.',
    terms: [['Amateur purpose', 'Non-commercial self-training, investigation and communication within the licence conditions.'], ['General reception', 'A transmission intended for whoever may be listening, rather than an appropriate amateur contact or permitted exception.'], ['Encryption', 'Concealing the meaning of a message; this is different from using a publicly understood code such as ordinary Morse.']],
    steps: ['Identify the purpose of the proposed contact. Personal experimentation belongs to the amateur context; paid delivery dispatch is a business purpose.', 'Check the audience and message arrangement. Amateur communication is not a general advertising or entertainment broadcast service. Initial CQ calls and other specified arrangements must be understood in their context.', 'Check whether a code merely represents information openly or conceals its meaning. The licence has specific encryption exceptions; an ordinary desire for privacy is not one of them.', 'Continue checking the rest of the conditions. A suitable purpose does not by itself settle band, power, identification, supervision or interference compliance.'],
    example: 'A friend asks to use the amateur station to coordinate a paid delivery round. The radios may work perfectly over that path, but technical success does not turn commercial dispatch into amateur self-training.',
    mistake: 'Reducing power or adding an optional suffix does not automatically make an otherwise unauthorised purpose acceptable.',
    sources: [syllabus(9, '1A1; 1C1; 1C2'), guidance],
  },
  supervision: {
    intro: 'Directly supervised operation lets another person use the station under the supervising licensee’s responsibility and conditions. It is not the visitor being granted an independent licence for the duration of the contact.',
    terms: [['Direct physical supervision', 'The licensee is physically present and able to take back control, as described by Ofcom guidance.'], ['Supervisor’s licence', 'The authorisation whose call sign and conditions govern that supervised operation.'], ['Responsibility', 'The licensee’s continuing obligation to ensure that the operation complies with the licence.']],
    steps: ['Identify which licensee is supervising and under which call sign the equipment is being operated. A visitor does not invent a temporary identity.', 'The person using the controls must operate within the supervisor’s applicable conditions, rather than the maximum capabilities printed on the radio.', 'The supervisor remains physically present so control can be regained. Compare that arrangement with being away from the equipment and available only by a message.', 'If the required supervision arrangement is absent, that particular supervised-use provision is not met. A person independently using their own qualification and licence is a different operating arrangement.'],
    example: 'At a club demonstration, an unlicensed friend can try the controls under the appropriate direct supervision. The supervisor remains beside the station, uses the governing identity and can intervene immediately.',
    mistake: 'Someone being able to telephone an experienced operator is not the same as direct physical supervision at the station.',
    sources: [syllabus(12, '1B1'), guidance],
  },
  userService: {
    intro: 'The licence includes particular provisions for User Service operation. A provision with a defined scope must be checked in that scope; it is not a general permission to use amateur equipment for any organisation or any business purpose.',
    terms: [['User Service provision', 'A specified circumstance in the licence allowing the relevant service-related use.'], ['Licence condition', 'A requirement or permission within the actual operating authorisation. The provision does not discard all its other conditions.'], ['Exception', 'A defined departure from a general rule, applying only when its stated circumstances are met.']],
    steps: ['First identify the operating context. An ordinary club exercise does not automatically become User Service operation merely because it resembles emergency traffic.', 'Consult the applicable provision and arrangements for the real activity. The responder-led context in this picture illustrates the distinction, rather than authorising a particular operation.', 'The Foundation syllabus expects recall that specified User Service use can occur. It does not examine the detailed identity of the service or circumstances under item 1B1.', 'The syllabus also identifies a specific encryption exception at the direct request of a User Service. That exception must not be expanded into ordinary encrypted private chat.'],
    example: 'Compare a normal club practice contact with a station participating in an appropriately arranged service exercise. The same equipment can be present, but the operating context determines which provision may apply.',
    mistake: 'The word emergency or exercise on its own is not proof that every requested use of the equipment is authorised.',
    sources: [syllabus(12, '1B1; 1C2'), guidance],
  },
  bandplan: {
    intro: 'A transmission occupies a range of frequencies, not only the number shown as its centre or dial setting. Band plans help different activities share a band. The licence schedule determines authority and restrictions; the plan helps coordinate how permitted users occupy the available space.',
    terms: [['Centre frequency', 'A reference location within the signal’s occupied spectrum.'], ['Bandwidth', 'The span of frequencies needed by a signal. A wider signal can overlap a neighbour even when the centre frequencies differ.'], ['Band plan', 'A coordinated arrangement of segments, modes and activities within a band. It does not replace the licence.']],
    steps: ['Locate your coloured transmission and the other user’s occupied range. The workbench uses arbitrary units so it does not invent a real allocation.', 'Move the centre while keeping width fixed. Compare the complete occupied ranges, including their edges.', 'Widen your transmission. An edge can cross into the neighbour’s range even though your centre setting has not changed.', 'For real exam lookups use the specimen plan in EX307. Its entries include modes, calling frequencies and protected activities. A live operating band plan and the exam specimen can differ.'],
    example: 'The other illustrated user occupies 70–80. Your signal centred at 60 with width 10 occupies 55–65 and is separate. With width 30 it occupies 45–75, so it overlaps. Different centres did not prevent the clash.',
    mistake: 'A blank-looking waterfall region is not operating permission. Check the licence allocation and its notes, then the appropriate band-plan arrangements.',
    sources: [syllabus(68, '7B1; 7B2; 1H1'), { title: 'RSGB EX307 specimen band plans', url: EXAM_SOURCES.reference }],
  },
  referenceCheck: {
    intro: 'The examination supplies reference information because you are expected to use it accurately. A schedule question is often a reading-across-the-row task: find the correct frequency range, then combine its status, service permission, power definition and footnotes.',
    terms: [['Primary / secondary status', 'Allocation status describing the relationship to other services. Secondary operation must protect the relevant primary services.'], ['ERP power limit', 'A limit expressed in effective radiated power, which includes antenna gain relative to a dipole. It is not always the same as transmitter output power.'], ['Footnote', 'A condition attached to an entry, potentially including geographical or other restrictions.']],
    steps: ['Use the current exam booklet, not a remembered value from a different band or an old printed manual. Find the row containing the frequency in the question.', 'Read the amateur-service status and, if relevant, the amateur-satellite-service entry. Permission in one column does not establish permission in another.', 'Read the maximum power and its definition. A number followed by ERP requires different interpretation from an output-power setting alone.', 'Read every applicable note before deciding. A geographical exclusion can make an operation unavailable even though the broad band and a power value appear in the table. The visual checklist supplies no substitute operating limits.'],
    example: 'In the January 2026 EX307 table, 431–432 MHz has a geographical restriction within 100 km of Charing Cross. Merely reading secondary and 25 W ERP would miss the decisive restriction. At 2400–2450 MHz the table instead lists 2 W, showing why one general Foundation power number is insufficient.',
    mistake: 'A band plan cannot grant a frequency or power privilege absent from the licence schedule. Read the correct document for the question being asked.',
    sources: [syllabus(16, '1H1'), { title: 'RSGB EX307: Schedule 1 and notes', url: EXAM_SOURCES.reference }],
  },
  exposure: {
    intro: 'RF exposure assessment considers people’s access to fields from the actual installation. A picture can show who may approach an antenna, but it cannot establish a compliant distance without the equipment, power, antenna and operating information that determine the exposure.',
    terms: [['EMF assessment', 'A check against the applicable electromagnetic-field exposure requirements using the relevant installation and operating details.'], ['Access', 'Where people can actually be during transmission, including ordinary unlicensed family members and visitors where public-exposure protection applies.'], ['Assessment record', 'Evidence of the assessment and its conclusion, including the justification when no further action is required.']],
    steps: ['Identify the relevant equipment and operating conditions. Transmit power, antenna gain and direction, transmission pattern and access all influence the assessment.', 'Identify who can enter the relevant areas. Being a family member or visitor does not provide an automatic exemption from the applicable public limits.', 'Compare the nearby and farther positions as a spatial idea only. The workbench intentionally gives no compliant distance: its drawing scale is not an exposure calculation.', 'Carry out the appropriate real assessment and retain its record. If thresholds or circumstances mean no additional action is necessary, keep the reason rather than assuming no record is needed.'],
    example: 'A visitor can stand beside a garden antenna while a station transmits. The operator needs to consider that access in the actual assessment. Copying the visitor’s position from this screen would not establish safety for another antenna or power setting.',
    mistake: 'EMC and EMF compliance are different checks. Equipment can avoid interference while still needing an exposure assessment, and an exposure assessment does not establish freedom from interference.',
    sources: [syllabus(16, '1G1; 8D1'), { title: 'Ofcom: EMF compliance guidance', url: 'https://www.ofcom.org.uk/siteassets/resources/documents/spectrum/emf/guidance-emf-compliance-enforcement.pdf?v=411682' }],
  },
  interference: {
    intro: 'Interference is an unwanted effect of one system on another. A useful investigation separates the source, the coupling route and the affected equipment. Changing one of them may change the symptom, but a successful radio contact or a single quiet trial does not explain the complete mechanism.',
    terms: [['Source', 'Equipment or a process producing unwanted electromagnetic energy, including a radio transmitter or noisy electronics.'], ['Coupling route', 'How that unwanted energy enters another device: for example through power, signal or antenna leads, or directly into its circuits.'], ['Immunity', 'A device’s ability to keep operating correctly in the presence of an electromagnetic disturbance.']],
    steps: ['Identify what goes wrong, in which device, and when. Keep the observed symptom separate from your first guess about its cause.', 'Compare the times with transmitter activity or other electrical equipment. Record frequency, mode, power and any relevant changes so the test can be repeated.', 'Change one appropriate variable at a time. Reducing transmit power tests one relationship; fitting suitable suppression near the affected device tests a possible entry route.', 'A choke or filter can reduce unwanted RF on a lead. It is not a universal cure: the correct remedy depends on the actual frequencies, coupling mechanism and device, while electrical safety must be preserved.'],
    example: 'A TV disturbance appears during some contacts. Compare the station log with the viewer’s recorded times, then agree controlled tests. If a suitable cable choke reduces the disturbance, that supports investigating the cable route; it does not prove every possible mechanism or justify modifying safety-critical equipment.',
    mistake: 'A neighbour’s complaint is neither proof of a faulty transmitter nor evidence that the transmitter cannot be involved. Cooperating to collect observations is more useful than blame.',
    sources: [syllabus(58, '6A1–6G2'), { title: 'RSGB EMC Committee: interference routes and investigation', url: 'https://rsgb.org/main/files/2019/09/EMC-Leaflet-4-Interference-to-Amateur-Radio-Reception-v1.0.pdf' }],
  },
  safety: {
    intro: 'A safety check asks how a person could be injured and which arrangement prevents exposure to that hazard. A station working electrically is not proof that its installation is safe. The picture lets you identify a mechanism, while the source sections provide the precautions relevant to the actual activity.',
    terms: [['Hazard', 'Something with the potential to cause harm, such as live conductors, a hot tool or unsecured access equipment.'], ['Isolation', 'Separating equipment from its energy source as appropriate before work. An ordinary front-panel control is not automatically complete isolation.'], ['Risk control', 'A suitable measure that removes the hazard or prevents people being exposed to it. Its adequacy depends on the real situation.']],
    steps: ['Identify the source of energy or injury and the person who could be affected. A low-voltage battery can still deliver a dangerous short-circuit current; an antenna installation can create both electrical and fall hazards.', 'Identify the path to injury: touching an energised conductor, bridging battery terminals, tripping on a lead, reaching too far from a ladder or entering a transmitting RF field.', 'Compare the safer arrangement and explain what path it changes. Keep protective earth and suitable protection intact; do not trade an electrical protection measure for an RF improvement.', 'Before real work, follow the manufacturer’s instructions and obtain competent help when required. The drawing is an educational comparison, not an inspection or certification of a real installation.'],
    example: 'A clearly marked isolation switch allows another person to cut the supply during an electrical accident. Its usefulness depends on access and other people knowing where it is; hiding it behind equipment removes much of that benefit.',
    mistake: 'Knowing a fact for the exam is not permission to perform work outside your competence. Stop and obtain appropriate help when you cannot establish a safe arrangement.',
    sources: [syllabus(73, '8A1–8F5'), { title: 'HSE: electrical, access and tool safety in construction', url: 'https://www.hse.gov.uk/pubns/priced/hsg150.pdf' }],
  },
  operating: {
    intro: 'Good operating procedure makes a contact understandable to the intended station and considerate to everyone sharing the channel. The sequence matters: first establish whether the frequency is available, then identify and call, then allow the other station a chance to respond.',
    terms: [['CQ', 'A general amateur call seeking a contact, used in an appropriate context and mode.'], ['Calling channel', 'A recognised place to find contacts, which should normally be freed once stations arrange a suitable working channel.'], ['QSY', 'An instruction or proposal to change frequency.']],
    steps: ['Listen before transmitting. A brief pause or quiet signal meter is not proof that nobody is using the frequency; a distant station may be weak at your location.', 'Check whether the frequency is in use using the appropriate operating practice. Avoid treating a desired channel as your personal reserved space.', 'Call and identify clearly. Use the call sign and a form appropriate to the mode, rather than relying on other people to recognise your voice.', 'Release transmit and listen for the reply. Once a VHF/UHF contact is established on a calling channel, arrange a suitable clear working frequency so others can also find contacts.'],
    example: 'Two stations meet on the FM calling frequency. They agree a possible working frequency, check it is clear, and continue there. Both the identification and the move help other users understand and share the activity.',
    mistake: 'A successful call does not give exclusive possession of the channel. Continue listening, identifying and operating considerately throughout the contact.',
    sources: [syllabus(66, '7A1–7A8; 7B1')],
  },
  phonetic: {
    intro: 'Individual letter names can sound similar or be lost in interference. A shared spelling alphabet replaces a short ambiguous letter name with a more distinctive agreed word. It represents letters precisely; it is not a separate call sign or a secret language.',
    terms: [['Spelling alphabet', 'An agreed word for each letter, such as Alfa for A and Bravo for B.'], ['Call-sign characters', 'The letters, digits and permitted additional parts used to identify the station.'], ['Phonetic spelling', 'Speaking the appropriate agreed word for each letter in sequence. The app displays it as text only.']],
    steps: ['Break the word or call sign into individual characters. Preserve their order rather than trying to invent a phrase with a similar sound.', 'For each letter, use its standard word. In particular, the standard spellings include Alfa and Juliett.', 'Keep digits and separators distinct from the letter words. The app writes ordinary digit names and Slash as a visible aid; it does not generate spoken training.', 'Use the alphabet to clarify identification or other exact text when needed. In an exam, recognise the standard word associated with the letter, not an informal local alternative.'],
    example: 'For the letters L, A and B, the sequence is Lima Alfa Bravo. A listener who misheard a brief letter sound can use the longer distinctive word to recover the intended character. The same principle helps when spelling a booking reference.',
    mistake: 'An improvised word beginning with the right letter is not the standard alphabet. Familiar alternatives may be less reliably recognised across different speakers.',
    sources: [syllabus(66, '7A5'), { title: 'NATO: the standard spelling alphabet', url: 'https://www.nato.int/en/news-and-events/articles/news/2017/12/21/nato-phonetic-alphabet-codes-and-signals' }],
  },
  report: {
    intro: 'A signal report separates how well the information can be understood from how strong the signal appears. A powerful interfering signal can still be unreadable. Reporting both properties is more informative than one vague claim that a contact is good or bad.',
    terms: [['Readability, R', 'How well the information can be understood, on a scale from 1 to 5.'], ['Strength, S', 'The reported signal strength, on a scale from 1 to 9 in the reporting code.'], ['Tone, T', 'The third part of an RST report, on a 1–9 scale, particularly relevant to the quality of a Morse note.']],
    steps: ['Assess readability first. The simulated message becomes more or less recoverable as this control changes; it is a teaching representation, not an automatic real receiver measurement.', 'Assess strength separately. The independent bars show why a large strength value need not force the readability value to be high.', 'Write an RS report with readability first and strength second. For an RST report, tone is added in the third position.', 'Use the standard meanings and order. The source topic also introduces other operating abbreviations, but the current Foundation reporting objective specifically requires the RST code and its scales.'],
    example: 'An RS report of 47 means readability 4 and strength 7. It does not mean strength 4, and 7 is not a permissible readability value. A strong signal with interference could have high S while R remains low.',
    mistake: 'These user-selected values are not a calibrated RF power measurement. Do not infer transmitter watts, exact distance or antenna gain from the illustrated report.',
    sources: [syllabus(70, '7E2')],
  },
  repeater: {
    intro: 'A repeater receives a radio signal at a useful high location and retransmits it so another station can receive it. This can join two paths that work even when the two handhelds cannot communicate directly. Each part of the route still has to function.',
    terms: [['Repeater input', 'The frequency on which the repeater receives users’ transmissions. Your radio transmits here.'], ['Repeater output', 'The frequency on which the repeater retransmits. Your radio receives here.'], ['Offset and CTCSS', 'The frequency difference between transmit and receive, and a specified access tone used by an appropriate analogue repeater.']],
    steps: ['The hill blocks the illustrated direct handheld-to-handheld path. More speaker volume does not remove that obstruction.', 'The hilltop receiver has a usable path from handheld A in the schematic. It receives on the repeater input frequency and retransmits on its output.', 'Handheld B receives that output on the other side. To reply, B also needs a usable path back to the repeater; simply hearing the output does not prove this.', 'Use the correct frequency arrangement, access settings and operating procedure. Check for other modes already using the channel. Repeater timeouts and short gaps help share the resource; simplex contacts should not occupy its intended operating frequencies.'],
    example: 'You can hear a repeater from a sheltered valley because its high antenna and transmitter reach you. Your low handheld, poor position or incorrect access tone can still prevent it hearing you. Check both path and settings rather than assuming one-direction reception proves a complete link.',
    mistake: 'A correct CTCSS tone does not amplify the handheld’s RF signal. It satisfies an access condition; a usable radio path is still needed.',
    sources: [syllabus(69, '7C1; 7C2')],
  },
  satellite: {
    intro: 'A spacecraft moves relative to a ground station, so the available radio path changes during a pass. The local horizon is one basic geometrical limit: a station cannot assume the same opportunity continues after the spacecraft moves below it. A real contact also depends on the spacecraft, service, frequencies and equipment.',
    terms: [['Pass', 'The changing opportunity as a spacecraft moves through the part of its orbit relevant to the ground station.'], ['Local horizon', 'The geometrical boundary between the sky above the observer and directions obscured by the Earth; local obstacles can add further restrictions.'], ['Satellite allocation', 'Spectrum made available for the amateur-satellite service, subject to the relevant schedule and conditions.']],
    steps: ['Move the spacecraft along the schematic arc. The line to the ground station shows how its direction changes, rather than a real measured orbit.', 'Above the horizon, a geometrical path can exist. That does not prove that the intended service is active, that a transponder is available or that the equipment is suitable.', 'Below the horizon, the direct path shown is obscured by the Earth. The opportunity can end while your own radio remains unchanged.', 'For actual operation use real pass predictions and the appropriate amateur-satellite allocations and sub-bands. Avoid disrupting satellite frequencies with ordinary terrestrial operation.'],
    example: 'You plan to receive an appropriate spacecraft transmission. A pass prediction gives the time and direction, and the service information gives frequencies and mode. This simulation teaches the moving geometry only; it supplies neither a live pass forecast nor transmitting permission.',
    mistake: 'Seeing the spacecraft above the drawn horizon is not a guarantee of a contact. Geometry, signal level, frequency changes during the pass and the service’s actual availability can all matter.',
    sources: [syllabus(71, '7G1'), { title: 'RSGB EX307: amateur-satellite allocation column', url: EXAM_SOURCES.reference }],
  },
  contactRecord: {
    intro: 'A station log records enough context to understand a contact later. It is useful for confirming contacts and comparing operation with interference reports. Routine good logging practice and a specific instruction from Ofcom to keep a log are separate matters.',
    terms: [['UTC', 'A shared time standard used to avoid ambiguity between local time zones and daylight-saving arrangements.'], ['Contact record', 'A record of when, where in spectrum, by what mode and with whom the communication occurred.'], ['QSL', 'A confirmation of a radio contact, for which accurate matching contact details are useful.']],
    steps: ['Record the date and UTC time. A local time without its time zone can be ambiguous to someone in another country.', 'Add the station worked, frequency and mode. A call sign alone does not tell an investigator which signal or operating period to compare.', 'Include reports and useful notes. For an interference investigation, related power or equipment observations may provide additional context.', 'If Ofcom specifically requires a log over a period, comply with that requirement. A normal voluntary record is useful, but its ordinary optional status is not a reason to ignore a formal requirement.'],
    example: 'A neighbour notes a disturbance at a particular time. Your log shows whether the station was transmitting then and on which band and mode. Comparing both records is more useful than remembering vaguely that you were on the air that evening.',
    mistake: 'A matching time is a lead for investigation, not automatic proof of the whole cause. Use the records to plan controlled tests and check the mechanism.',
    sources: [syllabus(67, '7A6; 6G2; 1D2')],
  },
  conduct: {
    intro: 'An operating response can either reduce a disruption or keep rewarding it with attention. Good practice protects the shared channel and other users while avoiding an escalating argument. Serious concerns should be handled through the appropriate advice or reporting route.',
    terms: [['Disruption', 'An interruption that interferes with legitimate use of the channel.'], ['Disengage', 'Stop prolonging the unproductive exchange and take an appropriate next operating action.'], ['Evidence', 'Useful observations such as times, frequencies and behaviour, distinguished from assumptions about identity or motive.']],
    steps: ['Recognise the interruption without treating every unclear or accidental signal as deliberate abuse. Keep the observed behaviour separate from assumptions.', 'Compare responding repeatedly with disengaging. A prolonged argument uses more of the channel and may give the disruptive person the attention they seek.', 'Continue appropriately, for example by ending the exchange or arranging a suitable change of frequency with the other legitimate station. Maintain proper identification and operating practice.', 'For a serious or continuing problem, record relevant facts and seek appropriate advice. Do not turn the station into a general-reception broadcast of allegations or personal details.'],
    example: 'A station repeatedly attempts to provoke insults during a contact. Refusing to continue the argument can reduce the reward for the interruption, while accurate observations can support later advice if needed.',
    mistake: 'A higher power setting or more offensive language is not a constructive cure. Music and offensive or threatening transmissions are unacceptable amateur operating practice.',
    sources: [syllabus(67, '7A7'), { title: 'Ofcom: handling amateur-radio misuse', url: 'https://www.ofcom.org.uk/spectrum/radio-equipment/licence-misuse-licence?language=en' }],
  },
  travel: {
    intro: 'Taking a radio into another country does not carry UK operating permission with it automatically. Equipment capability, the UK qualification and the destination’s authority are separate matters. Prepare the authorisation check before a holiday rather than discovering it when ready to transmit.',
    terms: [['Administration', 'The relevant national authority responsible for radio permissions in that jurisdiction.'], ['Recognition', 'Whether and how the destination accepts a qualification or licence from another jurisdiction.'], ['Authorisation', 'The actual permission and conditions that apply to the intended operation in the destination.']],
    steps: ['Identify the destination and the intended activity. Possessing a radio and being able to hear local signals are not themselves transmitting permission.', 'Check the destination authority’s current recognition arrangements. The Foundation syllabus recalls that other administrations do not routinely recognise the UK Foundation licence.', 'Check whether a local qualification, permit or other authorisation is required and which conditions would apply. Do not generalise arrangements for a UK Full licensee to Foundation.', 'Operate only when the relevant authorisation has been established. An optional /P or other suffix describes operation; it does not create missing permission.'],
    example: 'You pack a handheld that covers a holiday destination’s amateur bands. Before using its transmit button, establish whether your qualification is recognised and what the destination requires. A radio that tunes there may still be unauthorised for you to transmit there.',
    mistake: 'An apparently clear channel, a low power setting or a local station’s willingness to reply does not settle the destination’s licensing requirements.',
    sources: [syllabus(72, '7H1'), guidance],
  },
};

const topicGuides = {
  Modes_and_EMC: {
    intro: 'A nearby device can unintentionally act like part of a receiver. If RF couples into a susceptible circuit and that circuit detects amplitude variations, it can recover an unwanted version of the transmitted information. This is one mechanism behind the syllabus’s comparison of modulation modes.',
    terms: [['Unintended detection', 'A circuit converts part of an unwanted RF signal into a lower-frequency variation even though it was not intended to receive that radio transmission.'], ['Envelope', 'The outline of the RF wave’s amplitude. In AM it follows the information signal; in ideal FM it remains constant.'], ['Susceptibility', 'How readily the affected equipment malfunctions when exposed to an electromagnetic disturbance.']],
    steps: ['The source is the RF transmission, not the neighbour’s normal programme. Its field can couple into a cable or directly into an electronic circuit.', 'In the AM example, the RF envelope varies with the message. A circuit behaving as an unintended amplitude detector can convert those envelope variations into an unwanted low-frequency signal.', 'In ideal FM, this particular envelope remains constant. The illustrative amplitude detector therefore has no varying envelope message to recover. This is why the output trace becomes flat in this particular model.', 'The Foundation syllabus recalls AM and SSB as generally more likely to cause such problems than FM and some HF data modes. Real interference still depends on power, coupling, immunity and the mechanism: the mode name alone is not a guarantee.'],
    example: 'A susceptible powered speaker develops an unwanted voice-like disturbance during an AM transmission. A lead can collect RF and the input circuit can inadvertently detect it. A suitable filter or choke at the affected equipment may address the entry path; simply changing mode does not prove the installation has no remaining EMC issue.',
    mistake: 'The flat FM output in this example does not mean FM can never cause interference. It means this ideal amplitude-detection mechanism has no varying envelope to recover.',
    sources: [syllabus(59, '6B1; 6C1; 6D1'), waves],
  },
  EMC_and_Cars: {
    intro: 'A vehicle contains electrical systems that can both produce disturbances and be affected by an added radio installation. The aim is compatible operation of the whole vehicle, including its safety-related systems, rather than only a successful radio contact.',
    terms: [['Compatibility', 'The radio and vehicle systems working together without unacceptable interference or impaired safety.'], ['Stationary testing', 'Checking the installation while the vehicle is not moving, with relevant vehicle systems operating.'], ['Electrical noise', 'Unwanted signals from equipment such as ignition or charging systems that can impair reception.']],
    steps: ['Treat installation compatibility as the owner’s responsibility and obtain suitable professional advice. A connector fitting or the transmitter working is not a vehicle-system assessment.', 'Consider cables, power connections, antenna location and vehicle electronics together. Improvised changes to safety-critical systems are not an appropriate trial-and-error remedy.', 'Carry out the appropriate stationary tests with vehicle systems operating before any on-road tests. Watch for effects in either direction: radio affecting vehicle, and vehicle noise affecting radio reception.', 'Make the appropriate insurance disclosure and follow suitable installation guidance. A favourable comparison in this qualitative model is not approval of a particular real vehicle installation.'],
    example: 'Reception becomes noisy when the engine is running but is clearer when it is off. That observation supports investigating vehicle-generated interference; it does not identify a safe electrical modification by itself.',
    mistake: 'Increasing transmitter power cannot cure interference entering your receiver from the vehicle. Transmit performance and receive immunity are different sides of the problem.',
    sources: [syllabus(64, '6F1–6F3')],
  },
  EMC_and_Neighbours: {
    intro: 'An interference report is a problem to investigate cooperatively. Both the transmitting station and the affected equipment can matter. Clear records and agreed comparisons help separate a repeatable relationship from coincidence without assuming blame in advance.',
    steps: ['Ask what the symptom is, which device is affected, and when it happens. Record observations rather than deciding immediately which equipment must be faulty.', 'Compare the neighbour’s disturbance log with the station’s operating log. Matching frequency, mode, time and equipment details can suggest useful tests.', 'Agree controlled changes where appropriate. Changing one factor at a time makes the result interpretable; a single quiet trial does not establish a permanent cure.', 'Seek relevant EMC advice if the cause or remedy remains unclear. Preserve electrical safety and avoid unauthorised work on the neighbour’s equipment.'],
    example: 'A viewer records screen disturbances between 19:10 and 19:20. The station log shows an operating interval, band and mode. Repeating an agreed test and comparing the observations can provide much stronger evidence than either person’s memory of yesterday evening.',
    sources: [syllabus(65, '6G1; 6G2')],
  },
  EMC_Advice: {
    intro: 'Good technical advice starts with a description that another person can use to narrow down the mechanism. The adviser needs to know the symptom, operating conditions and controlled tests already performed, rather than only a statement that interference occurred.',
    steps: ['Describe the affected device and exactly what it does incorrectly. A visual disturbance, missing reception and unintended recovered speech suggest different possibilities.', 'Record times and the station’s frequency, mode, power and equipment arrangement. Include the other person’s observations where available.', 'Explain one-variable tests and their results, including trials that did not help. This helps prevent repeating an ineffective guess and makes the evidence reviewable.', 'Use the RSGB EMC Committee’s information, suitable leaflets and experienced club help. A real case may need further investigation; the workbench’s relative effect value is not a measurement to present as evidence.'],
    example: 'Instead of writing “my radio causes problems”, record “this device developed this symptom during these operating periods; changing this one setting produced this repeatable result”. That gives an adviser something concrete to test.',
    sources: [syllabus(65, '6G1; 6G2')],
  },
  Safety_Voltage_and_Current: {
    intro: 'Voltage and current are related but identify different parts of an electrical hazard. A voltage difference can drive current through a person. A source capable of large fault current can also heat conductors, start a fire or damage equipment, even when its normal voltage seems low.',
    terms: [['Shock hazard', 'A dangerous body-current path resulting from contact with energised conductors.'], ['Fault current', 'Current flowing through an unintended path, potentially much larger than normal load current.'], ['Isolation', 'Separating equipment from its energy source as appropriate before work, rather than assuming a front-panel control removes every hazard.']],
    steps: ['Identify both the operating voltage and the available energy or fault current. “Only a battery” does not remove the possibility of severe short-circuit heating.', 'Find how contact, damaged insulation or a metal object could complete an unintended path. Protection must address that path rather than merely whether the equipment still works.', 'Before suitable work inside equipment, disconnect the power and follow the manufacturer’s instructions, including any stored-energy precautions.', 'In an electrical accident the first action is to switch off the power. Do not touch a casualty who may still be connected to an energised source. Obtain appropriate emergency help.'],
    example: 'An exposed battery terminal touches a metal tool. The tool can bridge a low-resistance path, causing a large current and intense heating. The normal load’s modest current rating does not limit every possible fault.',
    sources: [syllabus(73, '8A1; 8A6–8A8')],
  },
  Mains_and_RF_Earths: {
    intro: 'Protective earthing and an RF-earth arrangement address different problems. A protective earth is part of protection against dangerous mains faults. An RF arrangement concerns radio-frequency current paths and interference. Solving the second problem must not defeat the first protection.',
    terms: [['Protective earth', 'A safety connection associated with the equipment’s electrical protection arrangement. A fitted safety earth must not be removed.'], ['RF earth', 'An intentional radio-frequency connection or arrangement used to manage RF current paths in an appropriate station design.'], ['PME', 'Protective multiple earthing, a supply arrangement requiring particular care and competent electrical advice before modifications.']],
    steps: ['Locate the mains equipment and its protective connection. In a fault, the safety arrangement and protective devices must work as designed.', 'Identify the separate RF issue, such as unwanted RF current using mains-related paths. A quieter receiver or reduced interference does not establish that a safety connection is dispensable.', 'Keep a fitted safety earth intact. Use suitable RF design, screening, filtering or other competent remedies instead of removing electrical protection.', 'Where PME or changes to earthing are involved, consult a competent electrical professional before modifications. A diagram does not establish the conditions of a real building supply.'],
    example: 'A station becomes quieter when a protective earth is removed. That observation may indicate an RF-current-path issue, but leaving the earth removed introduces a different danger. Restore the safety arrangement and obtain a suitable RF solution.',
    sources: [syllabus(73, '8A2; 6E2')],
  },
  Mains_Plugs_and_Fuses: {
    intro: 'A mains connection combines conductors with different functions and protective devices intended to interrupt dangerous conditions. Understanding the diagram helps recognise those functions; it is not permission to work on energised mains equipment.',
    terms: [['Live, neutral, earth', 'In standard UK flexible wiring, brown is live, blue neutral and green/yellow protective earth. Their functions must not be interchanged.'], ['Fuse', 'A protective element designed to melt and open the circuit under excessive current, selected according to the manufacturer’s requirements.'], ['RCBO', 'A residual-current circuit breaker with overcurrent protection, providing protection beyond a conventional fuse alone.']],
    steps: ['Identify the conductor functions and appropriate protection from the correct manufacturer and installation information. Colour knowledge does not establish that a real cable has been wired correctly.', 'A fuse opens when its element is heated by excessive current. It must not be bridged or arbitrarily increased merely because operation was interrupted.', 'Investigate a blown fuse’s cause before appropriate replacement. Suitable residual-current protection adds another protective function; it does not make live work safe.', 'Disconnect the supply before suitable inspection or work, follow the instructions and use competent help. Contact with both live and neutral can remain fatal even where residual-current protection is fitted.'],
    example: 'Replacing a repeatedly blown fuse with a larger value can stop the warning interruption while leaving the faulty circuit inadequately protected. The useful question is why excessive current occurred and what protection is specified.',
    sources: [syllabus(73, '8A3–8A6')],
  },
  Battery_Safety: {
    intro: 'A battery’s low voltage can hide its ability to deliver very large current into a short circuit. The hazard in this picture is the metal bridge between opposite terminals. Removing that unintended path and using suitable handling and protection address the cause.',
    terms: [['Short circuit', 'An unintended low-resistance path, such as metal bridging battery terminals.'], ['Chemistry', 'The type of electrochemical cell, which determines appropriate handling and charging methods.'], ['Charging control', 'The suitable voltage, current and termination arrangements specified for the particular battery or pack.']],
    steps: ['Trace the metal bridge from the positive terminal to the negative terminal. It bypasses the intended controlled load.', 'The resulting low-resistance path can allow a large fault current. Heating can damage the object or cells and can cause fire.', 'Protect exposed terminals from loose conductive objects and use the specified fault protection and handling arrangements. A disconnected device does not make loose battery terminals safe to short.', 'Charge only with equipment and methods suited to the battery chemistry and manufacturer’s instructions. Lithium batteries in particular can present fire or explosion hazards when mishandled.'],
    example: 'A loose cell carried with keys can have its terminals bridged. A battery-powered radio being switched off does not prevent this separate fault path in a spare cell carried beside it.',
    sources: [syllabus(75, '8A8; 2J1')],
  },
  Shack_Safety: {
    intro: 'A safe station lets people identify and reach its controls without creating new hazards around the desk. Emergency isolation, cable routing and other people’s access matter even when every radio is operating normally.',
    terms: [['Main isolation control', 'A clearly identified control for cutting the station’s relevant supply in an emergency, with its location known to others.'], ['Trip hazard', 'An object or lead in an access route that can cause a person to fall.'], ['Insulation damage', 'Wear or damage that can compromise protection from unintended electrical contact.']],
    steps: ['Identify how the station can be switched off and whether someone else could find that control if the operator is unable to act.', 'Trace leads through the room. Cables across walking routes can trip people, pull equipment down or suffer damage.', 'Arrange access and cable protection appropriately rather than hiding essential controls behind equipment. Consider visitors as well as the regular operator.', 'Repeat the check when the station layout changes. A newly added supply, charger or portable lead can introduce a hazard into an otherwise familiar arrangement.'],
    example: 'A temporary charger lead crosses the doorway during a session. Rerouting and suitably protecting it removes a trip and wear mechanism that changing a radio setting could never address.',
    sources: [syllabus(75, '8A7; 8F2; 8F5')],
  },
  Working_at_Height: {
    intro: 'Antenna work can involve falls, unstable access equipment and falling objects. The purpose of the comparison is to identify these mechanisms before attempting work, not to turn a schematic ladder position into approval of an actual site.',
    terms: [['4:1 ladder guide', 'About four units of vertical rise for one unit of base distance out, where appropriate for the ladder and task.'], ['Securing', 'Preventing the access equipment from slipping or moving using the appropriate arrangement.'], ['Overreaching', 'Moving too far away from a supported working position, which can lead to loss of balance or a fall.']],
    steps: ['Consider whether the task can be done without work at height. If access is needed, use suitable equipment and competent assistance for the real conditions.', 'A ladder requires suitable footing, angle and securing. The exam’s 4:1 guide does not replace the ladder instructions or an assessment of the supporting surfaces.', 'Avoid overreaching and carry tools appropriately. A tool belt or similar arrangement can reduce the temptation to climb while holding loose items.', 'Consider people below as well as the person above. Appropriate protection, help and a controlled working area matter; stop when the arrangement cannot be made suitable.'],
    example: 'With a suitable ladder reaching about 4 m vertically, the guide suggests a base about 1 m out. That is one check, not the whole safety decision: footing, securing, access, task and surrounding hazards still need assessment.',
    sources: [syllabus(77, '8C1–8C3'), { title: 'HSE: ladder precautions and the 4:1 guide', url: 'https://www.hse.gov.uk/pubns/priced/hsg150.pdf' }],
  },
  Antenna_Safety: {
    intro: 'Antenna siting must consider the installation’s possible movement and failure, not only where it stands in calm weather. Contact with overhead power lines, or electrical arcing without direct contact, can be lethal. A better radio location is not a sufficient reason to accept that hazard.',
    terms: [['Clearance', 'Separation from a hazard under the relevant real conditions, not merely a gap measured on this drawing.'], ['Arcing', 'Electric current crossing a gap under suitable electrical conditions; direct metal-to-metal contact is not always required for injury.'], ['Support system', 'The mast, fixing, guys and other parts that hold and control the antenna’s position.']],
    steps: ['Identify overhead lines and other hazards before choosing the antenna or access position. Include the feeder and any ladder or erection tool.', 'Consider how the wire, mast, support or ladder could swing or fall. Clearance in the final upright position is not enough if erection or failure can bring it dangerously close.', 'Keep the complete arrangement well clear and obtain suitable professional advice where needed. The sketch intentionally provides no universal numerical clearance.', 'Secure and locate the installation appropriately for its real loads and access. Review the arrangement after changes or adverse conditions.'],
    example: 'A mast is clear of a power line while upright, but its full length could reach the line if it fell. Moving the chosen site can remove that fall-path hazard before the mast is erected.',
    sources: [syllabus(79, '8F1; 8C1')],
  },
  RF_Safety: {
    intro: 'RF safety includes exposure to the electromagnetic field and direct contact with RF-carrying parts. These are related but distinct hazards. Antenna power, gain, operating pattern and access must be considered rather than assuming that the radio’s normal operation proves the surroundings are safe.',
    terms: [['RF exposure', 'A person’s exposure to radio-frequency electromagnetic fields from the installation.'], ['Tissue heating', 'The principal RF health effect recalled by the Foundation syllabus; the eyes are particularly susceptible.'], ['RF contact hazard', 'Injury, including burns, from contacting conductors carrying RF during transmission.']],
    steps: ['Identify where people can be while the station transmits. Position antennas to avoid accidental contact with RF-carrying parts.', 'Assess exposure using the relevant installation information. The illustrated nearby and farther positions are not a compliant-distance calculation.', 'Take particular care around high-gain microwave antennas and waveguides. Do not look into a transmitting waveguide or stand close in front of a transmitting high-gain microwave antenna.', 'Apply the appropriate controls and retain the required assessment record. Changes in power, antenna or access may require the real arrangement to be reconsidered.'],
    example: 'A garden antenna can be electrically connected and working while visitors can still reach an RF-carrying element. Suitable siting and access control address the contact mechanism; an SWR reading does not assess it.',
    sources: [syllabus(77, '8D1–8D4; 1G1'), { title: 'Ofcom: EMF compliance guidance', url: 'https://www.ofcom.org.uk/siteassets/resources/documents/spectrum/emf/guidance-emf-compliance-enforcement.pdf?v=411682' }],
  },
  Car_Safety: {
    intro: 'A mobile installation must coexist safely with the vehicle’s systems. A successful transmitted signal is only one part of that decision. Professional installation advice and appropriately controlled tests are important before relying on the radio while travelling.',
    terms: [['Vehicle compatibility', 'The radio installation not impairing the vehicle’s electrical, management or safety systems.'], ['Stationary test', 'Testing while the vehicle is not moving and relevant vehicle systems are operating.'], ['Distraction', 'Attention taken away from the driving task, for example while attempting an equipment adjustment.']],
    steps: ['Use suitable professional advice for the installation and ensure the vehicle owner’s responsibility and appropriate insurance disclosure are addressed.', 'Check antenna, cable, power and equipment arrangements as a system, including whether equipment can move or interfere with controls.', 'Carry out appropriate stationary tests with vehicle systems operating before any on-road testing. Do not use an on-road symptom as a reason to experiment with safety-critical systems while moving.', 'Arrange adjustments so that driving remains the priority. The scene’s parked arrangement illustrates stopping in a safe place before adjusting the equipment; it is not a complete road-law or vehicle-installation checklist.'],
    example: 'An adjustment is needed during a journey. Preparing controls before departure or stopping safely for the adjustment avoids combining an unfamiliar radio operation with the driving task.',
    sources: [syllabus(64, '6F1; 6F2; 8F5')],
  },
  Outdoor_Safety: {
    intro: 'Portable operation creates a changing work area rather than a fixed safe desk. Moisture, temporary power connections, people’s access, weather and terrain can alter the hazards during the session. The decision to stop is therefore part of operating the station.',
    terms: [['Temporary installation', 'Equipment and supplies arranged for a limited activity, which still need suitable protection and siting.'], ['Damp conditions', 'Conditions that can worsen electrical contact and insulation hazards, particularly with temporary mains supplies.'], ['Changing conditions', 'Weather, access or terrain changes that can make the original arrangement unsuitable.']],
    steps: ['Assess the site before setting up, including public access, overhead lines, cable routes and the proposed supply.', 'Use appropriate equipment and protection for the conditions. Temporary mains leads, damp ground and exposed connections require particular care and competent advice where needed.', 'Review conditions during the session rather than relying only on the initial check. Approaching severe weather or a changed access route can require operation to stop.', 'Do not carry out adjustments or repairs to live exposed equipment. Follow the relevant instructions and obtain help when uncertain about a safe arrangement.'],
    example: 'A lead route that was dry and clear becomes wet and crossed by visitors as an outdoor event changes. The operator needs to reconsider the arrangement and may need to stop, even if the radio link remains excellent.',
    sources: [syllabus(80, '8F4; 8F5; 8E1')],
  },
  Finally_on_Safety: {
    intro: 'The final check is a deliberate search for practical paths to injury before operating. It includes electricity, heat, tools, falls, RF, weather and other people. Treat it as part of using the station rather than a list remembered only for examination questions.',
    steps: ['Identify the energy sources and how to isolate them. Keep suitable electrical protection and a fitted safety earth intact.', 'Check access, cable routing and equipment stability. Include visitors and people who might need to find the main switch.', 'For installation or maintenance, use suitable tools, eye protection, ventilation and access arrangements. A hot soldering iron, flying swarf and falling objects need different controls.', 'Remain alert to changing or newly unsafe conditions. Warn others and report or address the issue appropriately; safety is not delegated only to the most experienced operator present.'],
    example: 'Before switching on, locate the main isolation control, clear the access route and check that nobody can contact transmitting antenna parts. If work is planned, add the precautions specific to the tool and task rather than assuming the operating checks cover it.',
    sources: [syllabus(75, '8A7; 8B1; 8B7; 8F5')],
  },
};

export function guideFor(activity) { return guides[activity.kind] ? { ...guides[activity.kind], ...topicGuides[activity.topic] } : null; }

export function guideHtml(activity, title = activity.topic.replaceAll('_', ' ')) {
  const guide = guideFor(activity);
  if (!guide) return '';
  return `<section class="guided-explanation" aria-labelledby="guide-title"><span class="small-label">Build the idea from the beginning</span><h2 id="guide-title" tabindex="-1">Understand ${esc(title)}</h2><p>${esc(guide.intro)}</p><details class="guide-terms" open><summary>What the terms mean</summary><dl>${guide.terms.map(([term, meaning]) => `<dt>${esc(term)}</dt><dd>${esc(meaning)}</dd>`).join('')}</dl></details><h3>How it works, step by step</h3><div class="guide-steps">${guide.steps.map((step, index) => { const boundary = step.indexOf('. '); const heading = boundary < 0 ? `Step ${index + 1}` : step.slice(0, boundary + 1); const body = boundary < 0 ? step : step.slice(boundary + 2); return `<details ${index === 0 ? 'open' : ''}><summary><span>${index + 1}</span>${esc(heading)}</summary><p>${esc(body)}</p></details>`; }).join('')}</div><details class="guide-example" open><summary>Worked example and real consequence</summary><p>${esc(guide.example)}</p></details><details class="guide-mistake"><summary>A common misunderstanding</summary><p>${esc(guide.mistake)}</p></details><p class="guide-sources">${guide.sources.map(source => `<a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(source.title)} ↗</a>`).join('<br/>')}</p></section>`;
}

export function explainState(activity, values) {
  const result = readings(activity, values);
  const number = value => new Intl.NumberFormat('en-GB', { maximumFractionDigits: 4 }).format(value);
  if (activity.kind === 'signal') {
    if (values.missing === 'oscillator') return 'The oscillator is off, so this simplified transmitter has no RF carrier. A message input cannot modulate a carrier that has not been generated. The later RF amplifier therefore has no intended RF signal to amplify, and this model shows no useful output. This differs from losing only the message input.';
    if (values.missing === 'modulator') return 'The RF carrier is still being generated, but the message input is missing. The modulator therefore has no changing information with which to vary the carrier. In this ideal chain the steady carrier continues to the RF amplifier and antenna. A receiver may detect RF energy while recovering none of your intended message. We are simulating a missing message input, not physically removing a complete RF-path stage.';
    if (values.missing === 'amplifier') return 'The carrier and message-processing functions are present, but the model’s RF output stage is disabled. It therefore blocks the useful transmitted output. A real fault could leave small leakage signals, so this binary diagram is not a measurement of an actual broken transmitter. Repairing message settings would not restore a disabled output stage.';
    return 'The oscillator supplies the carrier; the message input controls the modulator; the RF amplifier increases signal power using the supply; and the antenna couples the resulting RF signal into a wave. Both a carrier source and the intended message are present, so this model produces modulated RF output.';
  }
  switch (activity.kind) {
    case 'battery': { const pack = batteryPack(values.cells, values.connected === 'on'); return `The ${values.cells} ideal 1.5 V cell${values.cells === 1 ? '' : 's'} provide ${number(pack.voltage)} V${values.cells > 1 ? ' because series cell voltages add' : ''}. ${values.connected === 'on' ? `The connected 6 Ω load completes a path, so I = V/R = ${number(pack.voltage)}/6 = ${number(pack.current)} A. Energy is transferred to that load at ${number(pack.power)} W.` : 'The load path is open, so current and delivered power are zero. The cells still store chemical energy and their terminal voltage remains in this ideal model.'} A real device must use its specified supply; adding cells is not automatically a suitable upgrade.`; }
    case 'circuit': return `${number(values.voltage)} V is applied across ${number(values.resistance)} Ω. Using I = V/R gives ${number(values.voltage)}/${number(values.resistance)} = ${number(result.value)} A. At the same voltage, a larger resistance opposes the flow more and gives a smaller current. The resistor converts electrical energy into heat. ${result.detail}. The ideal calculation assumes a fixed resistor, not every possible electronic load.`;
    case 'wave': return `At ${number(values.frequency)} MHz, λ = 300/${number(values.frequency)} = ${number(result.value)} m. That is the distance of one complete spatial cycle. An ideal quarter-wave element would be ${number(antennaElementLength(values.frequency))} m long. This changes the space an antenna design needs, while radio-wave speed in air remains approximately the same. The labelled wave window can rescale; read its metre labels before comparing drawings.`;
    case 'power': return `The load is drawing ${number(values.current)} A at ${number(values.voltage)} V. Multiply the two: P = V × I = ${number(values.voltage)} × ${number(values.current)} = ${number(result.value)} W. That means ${number(result.value)} joules transferred each second. The model states an operating current; a charger’s maximum current rating does not force that current through every device.`;
    case 'series': { const lamps = lampCircuit(values.layout, values.fault === 'open'); return values.fault === 'open' ? values.layout === 'series' ? 'The first lamp is open circuit. Both lamps share one series route, so the break stops current through both: neither has a complete path back to the source. The 6 V source still exists; it has not been used up by the failure.' : 'The first parallel branch is open, but the second branch still joins both supply terminals. Its 6 Ω lamp therefore still has 6 V across it and draws 1 A. A fault in one separate branch does not break the other ideal branch.' : `In this ${values.layout} arrangement, the lamp currents are ${number(lamps.currents[0])} A and ${number(lamps.currents[1])} A. ${values.layout === 'series' ? 'The shared path has 12 Ω total resistance, giving 6/12 = 0.5 A. Each equal lamp has 3 V across it.' : 'Each lamp is across the full 6 V, so each draws 6/6 = 1 A. The source supplies their sum, 2 A.'}`; }
    case 'connection': return activity.topic === 'Connectors' ? values.connected === 'on' ? 'The connector halves are joined, so the intended RF path is restored in this qualitative picture. Correct connector type, inner contact and outer-screen termination remain necessary. The drawing does not measure impedance, shielding or loss.' : 'The connector halves are separated. That interrupts the intended connection before any change to frequency or modulation could repair it. Inspecting a suitable accessible connection is therefore a different diagnostic step from adjusting the radio.' : values.connected === 'on' ? 'Closing the switch joins the conducting path. The ideal 3 V source can now drive current through the 6 Ω lamp and back to the source: I = 3/6 = 0.5 A. The lamp receives electrical energy, represented by the lit symbol.' : 'The open switch breaks the lamp’s only path, so no steady current flows in this ideal circuit and the lamp is off. The battery can still have 3 V across its terminals. An open load is not the same as an absent battery.';
    case 'tuner': return `${result.detail}. ${result.text === 'Neither example selected' ? 'The simplified selection window includes neither programme, so no fictional programme is recovered. It does not mean both transmitters have stopped.' : `The receiver’s selection and recovery stages produce the ${result.text.toLowerCase()} text display.`} Turning the tuning control changes which input is selected, rather than changing the speed of the transmitted waves. The model replaces programme sound with text.`;
    case 'modulation': return activity.topic === 'Modes_and_EMC' ? values.mode === 'am' && values.depth > 0 ? 'The AM envelope varies with the message. The susceptible-device illustration detects that unwanted amplitude variation and produces a lower-frequency output trace. This explains one route by which a radio transmission can appear in equipment that was not intended to receive it. The result depends on the coupling and device; it is not a prediction for every neighbour’s equipment.' : 'There is no varying envelope for the ideal amplitude detector to recover in this state. This may be because the example uses constant-amplitude FM or because message strength is zero. Other interference mechanisms can still exist, so a flat output here is not a real-installation EMC certificate.' : values.depth === 0 ? 'Message strength is zero, so this normalised model adds no message-driven variation to the RF signal. A steady carrier remains. The receiver could detect its presence without recovering the intended changing voice or data.' : values.mode === 'am' ? 'The message is controlling carrier amplitude: the envelope becomes taller and shorter while the rapid RF cycle spacing remains substantially constant. An AM receiver recovers the information from that amplitude variation. Increasing message strength makes the variation more pronounced in this model.' : 'The message controls instantaneous frequency about the carrier value. RF cycles become closer and farther apart while their height stays constant. An FM receiver recovers those frequency changes; an amplitude-only interpretation would miss the intended information.';
    case 'digital': return `The input curve is unchanged, but ${values.samples} sampled values now represent it across the same view. More closely spaced measurements can follow its changes more closely in this example. The computer receives values taken at those instants, not an unlimited continuous voltage. Real systems also need suitable sample rate, resolution, conversion and compatible processing; the count shown is not an actual SDR sampling specification.`;
    case 'powerType': return values.supply === 'dc' ? 'The voltage trace stays on one side of zero, representing fixed polarity from a steady battery. A suitable resistive load therefore has one current direction. The flat shape does not mean no energy is being transferred; a constant DC supply can power a working device.' : 'The trace crosses zero and changes sign repeatedly. That sign change represents reversed voltage polarity and, for the suitable resistive load being considered, reversed current direction. One full positive-and-negative sequence is a cycle. A device requiring DC needs an appropriate conversion and regulation arrangement.';
    case 'feeder': return `The feeder receives 10 W but delivers ${number(result.value)} W to the antenna at the selected example loss. The missing power is dissipated along the line rather than usefully reaching the antenna. This also weakens a received signal travelling in the opposite direction. The heat marks illustrate loss; they are not reflected power returning from a mismatch.`;
    case 'matching': return `At SWR ${number(values.swr)}:1, the ideal lossless model reflects ${number(result.value)}% of the forward power. A mismatch makes forward and reflected waves coexist on the feeder. Investigate the antenna system and connections rather than treating a high SWR as proof of a faulty transmitter. Matching and efficient radiation are separate checks.`;
    case 'bandplan': return `Your illustrated signal extends from ${number(values.centre - values.width / 2)} to ${number(values.centre + values.width / 2)}. The other user occupies 70–80. ${signalsOverlap(values.centre, values.width) ? 'The occupied ranges overlap, even if their centre settings differ.' : 'These occupied ranges are separate in this example.'} Compare the edges as well as the centres. These are arbitrary units: actual permissions and operating segments require the licence schedule and the appropriate band plan.`;
    case 'propagation': return values.band === 'hf' ? 'The curved route represents a possible HF return through the ionosphere, beyond the direct horizon. Whether that route works depends on frequency and changing ionospheric conditions, including time and solar activity. Adding a hill to the direct route does not guarantee or prevent every possible skywave path.' : values.obstacle === 'blocked' ? 'The hill obstructs the direct VHF/UHF route in this picture. Terrain can create a radio shadow even when both radios work. A suitable higher or clearer position may improve both transmit and receive paths; increasing only one radio’s power cannot remove every path problem.' : 'The picture now has an unobstructed direct route. That removes the illustrated hill problem, but it does not calculate range or guarantee intelligible communication. Antenna height, signal level, interference and real surroundings remain relevant.';
    default: return `${result.label}: ${result.text ?? `${number(result.value)} ${result.unit}`}. ${result.detail}. ${activity.scenario.result}`;
  }
}
